        // "sumar" → a + b
        // "restar" → a - b
        // "multiplicar" → a * b
        // "dividir" → if b != 0, a / b; otherwise, show an error and use 0
        // default → 0
        // Use yield for division (needs a block)
        // Prints: "8.0 multiplicar 3.0 = 24.0"

    }
}

solution:
public class CalculadoraSwitch {
    public static void main(String[] args) {
        String operacion = "multiplicar";
        double a = 8.0;
        double b = 3.0;

        double resultado = switch (operacion) {
            case "sumar" -> a + b;
            case "restar" -> a - b;
            case "multiplicar" -> a * b;
            case "dividir" -> {
                if (b == 0) {
                    System.out.println("Error: cannot divide by zero");
                    yield 0;
                }
                yield a / b;
            }
            default -> 0;
        };

        System.out.printf("%.1f %s %.1f = %.1f%n", a, operacion, b, resultado);
    }
}

